'use strict';
async function init(){if(!window.supabase){message('No se ha podido cargar Supabase. Comprueba tu conexión a internet.',true);return}db=window.supabase.createClient(URL,KEY);const params=new URLSearchParams(location.search);if(params.get('type')==='recovery'||location.hash.includes('type=recovery')){setTimeout(async()=>{const password=prompt('Introduce tu nueva contraseña (mínimo 6 caracteres):');if(password&&password.length>=6){await action(async()=>{requireOk(await db.auth.updateUser({password}));message('Contraseña actualizada.');await refresh()})}},700)}await action(refresh)}init();
